 * reads back as this exact number, its point shifted by counting rather than by
 * multiplying, and then rounded half-up. `.995` shifts to exactly 99.5, which
 * rounds to 100, which carries to 1.
 *
 * @param value Any number from 0 up.
 */
function twoFigures(value: number): { figures: number; exponent: number } | null {
  if (!Number.isFinite(value) || value <= 0) {
    return null;
  }
  const [mantissa = "0", place = "0"] = value.toExponential().split("e");
  let exponent = Number(place);
  // The two figures, as a whole number from 10 to 99.
  let figures = Math.round(Number(`${mantissa}e1`));
  if (figures >= 100) {
    // Rounding up carried into the next place: .0999 becomes .10, not .100.
    figures = 10;
    exponent += 1;
  }
  return { figures, exponent };
}

/**
 * Write those two figures out.
 *
 * Both digits are always printed — `.060` keeps its trailing nought, because
 * dropping it would claim less precision than we have, and "two figures except
 * when the second is a nought" would be a second rule for one ugly case.
 */
function written({ figures, exponent }: { figures: number; exponent: number }): string {
  if (exponent < 0) {
    return `.${"0".repeat(-exponent - 1)}${figures}`;
  }
  const digits = `${figures}`;
  // A number at or above one: the point sits inside or after the two figures.
  return exponent === 0 ? `${digits[0]}.${digits[1]}` : digits + "0".repeat(exponent - 1);
}

/**
 * Print a **likelihood** — or an end of the range around one, which is a
 * likelihood too — the way this product prints one.
 *
 * **A likelihood, and only a likelihood.** How far a number moved and how wide a
 * band is are measured on the same scale and are not likelihoods; they take
 * `toSize` below, and the difference is the guard.
 *
 * **Two significant figures.** A likelihood is between zero and one, so the
 * leading zero is dropped: `.35`, not `0.35`. Both figures are always printed.
 *
 * **It never prints a certainty, at either end.** A likelihood of 1 says the
 * thing cannot fail and a likelihood of 0 says it cannot happen, and nothing on
 * this map is entitled to either. So the guard is applied to the number **as it
 * would print**: what two figures would print at or above `1.0` prints `>.99`,
 * and what they would print below `.010` prints `<.01` (Kent, 2026-09-20, G10).
 * `.0099` is below the line and reads `<.01`; `.010` is on it and reads `.010`.
 *
 * **This rule is written twice and the two copies must move together.** The
 * engine writes the same numbers into the one-line summary it carries, in
 * `backend/src/katalyst/domain/diff.py::_two_figures`. A screen and a sentence
 * that round the same number differently are two answers to one question.
 *
 * @param value A likelihood, at full precision.
 * @returns The number as it is shown on screen.
 */
export function toTwoFigures(value: number): string {
  if (!Number.isFinite(value) || value <= 0) {
    return "<.01";
  }
  if (value >= 1) {
    return ">.99";
  }
  const rounded = twoFigures(value);
  if (rounded === null) {
    return "<.01";
  }
  // Read off the printed value rather than the one that came in. Two figures
  // put the point one place after them, so anything below a hundredth lands at
  // an exponent under −2 — and `.00996` rounds up to `.010` and stays.
  if (rounded.exponent >= 0) {
    return ">.99";
  }
  if (rounded.exponent < -2) {
    return "<.01";
  }
  return written(rounded);
}

/**
 * Print a **size** on the likelihood scale: how far a number moved, or how wide
 * a band is.
 *
 * **A size is not a likelihood, and it takes no guard.** `<.01` on a likelihood
 * says "nothing here, but we are not calling it impossible" — a claim about the
 * world. A move of nine thousandths is not a claim about the world at all; it is
 * a measurement, and rounding it away to `<.01` would throw out the only thing
 * the reader came for. So two significant figures, however small: `.0090`,
 * `.0035`, `.00012` (Kent, 2026-09-20, G10).
 *
 * The other end takes no guard either: a move of exactly one is a real move, and
 * it prints `1.0`.
 *
 * **Nought and not-a-number are two different things.** A move of exactly
 * nothing prints `0` — two significant figures of nothing is still nothing, and
 * `.00` would claim a precision the measurement has not got. Anything that is
 * not a number at all prints the dash this product prints for a value that is
 * not there, rather than being rounded down to nought and read as a measurement.
 *
 * @param value A distance between two likelihoods, at full precision. Its sign
 *   is said in words elsewhere, so pass its size.
 */
export function toSize(value: number): string {
  if (!Number.isFinite(value)) {
    return "—";
  }
  const rounded = twoFigures(Math.abs(value));
  return rounded === null ? "0" : written(rounded);
}

/** The chevron and the word each direction goes by. Neither is a colour. */
const WAY = {
  up: { chevron: "▲", word: "up" },
  down: { chevron: "▼", word: "down" },
} as const;

/**
 * How far a number moved, in the one form every surface prints it in.
 *
 * **Never a chevron between two readings that print the same.** Two figures is
 * the whole of what this product shows, and a move smaller than the second
 * figure leaves the before and the after printing identically — `.36 ▲ .36`,
 * which says "it went up" and "it is where it was" in the same breath and reads
 * as a fault in the tool. So where the two readings differ the row is the pair
 * with the chevron between them, and where they do not it is the one reading and
 * the size of the move in words: `.36 · up by .0090`.
 *
 * The size is the engine's own, at two significant figures **and no guard**: a
 * move of nine thousandths is a measurement, not a claim about the world, and
 * rounding it away to `<.01` would throw out the only thing the reader came
 * for (Kent, 2026-09-20, G10).
 *
 * @param from The first world's likelihood, at full precision.
 * @param to The second world's likelihood, at full precision.
 * @param by How far it moved, as the engine reported it. Its sign is already
 *   said by `way`, so only its size is printed.
 * @param way Which way it went, as the engine read it.
 */
export function toMovement(from: number, to: number, by: number, way: "up" | "down"): string {
  const before = toTwoFigures(from);
  const after = toTwoFigures(to);
  if (before !== after) {
    return `${before} ${WAY[way].chevron} ${after}`;
  }
  // Nothing moved at all — the engine's own difference is zero — so there is no
  // direction to name. "up by 0" would be a direction invented for a number that
  // has none.
  if (by === 0) {
    return after;
  }
  return `${after} · ${WAY[way].word} by ${toSize(by)}`;
}

/**
 * Print a range the way this product prints one: `.22–.50`.
 *
 * Both ends are likelihoods, so both take the guard: a band whose bottom end
 * sits under a hundredth reads `<.01–.03`, which says the low end is small
 * without calling it impossible.
 *
 * The dash is an en dash, the one used for a span between two numbers.
 */
export function toRange(lo: number, hi: number): string {
  return `${toTwoFigures(lo)}–${toTwoFigures(hi)}`;
}

/**
 * Print a share of something counted — *how many of the two thousand versions
 * of the map moved the same way* — as a whole percentage.
 *
 * A share is not a likelihood. It is a count of things that happened divided by
 * how many there were, so a hundred per cent really can mean *every one of
 * them*, and printing `>.99` over it would hide a fact the machine actually
 * counted. So the only guard here is the one that stops rounding from inventing
 * unanimity: a share that is not quite all of them never prints as all of them.
 *
 * Two figures, like everything else on screen: `97%`, never `96.63%`.
 *
 * @param share A share from 0 to 1, at full precision.
 */
export function toShare(share: number): string {
  if (!Number.isFinite(share)) {
    return "—";
  }
  const whole = Math.round(share * 100);
  if (whole >= 100 && share < 1) {
    return ">99%";
  }
  if (whole <= 0 && share > 0) {
    return "<1%";
  }
  return `${whole}%`;
}

/**
 * The whole reading, in the form a sentence would use: `.35 (.22–.50)`.
 *
 * This is what the chip is called when it is read aloud, and what the tile uses
 * when it needs the reading inside a longer sentence.
 */
export function toReading(p: number, lo: number, hi: number): string {
  return `${toTwoFigures(p)} (${toRange(lo, hi)})`;
}

/** The word each owner is called by on screen. */
const OWNER_WORDS: Record<BeliefOwner, string> = {
  model: "model",
  user: "user",
  market: "market",
};

/**
 * The note a chip opens when you look at it: one label, one sentence.
 *
 * It is not a pop-up. It is a shelf that slides out from the bottom edge of the
 * tile, drawn on the tile's own surface, and it needs no dismissing — look
 * away, or move the keyboard on, and it closes itself.
 */
interface Note {
  /** The chip's label, printed as the first line of the shelf. */
  readonly label: string;
  /** The sentence under it. */
  readonly sentence: string;
}

/** Group a count in thousands the way the sentence below writes it: `2 000`. */
function inThousands(count: number): string {
  return count.toLocaleString("en-GB").replace(/,/g, " ");
}

/**
 * What the model chip says about itself — and there are two answers, because
 * there are two different things a range can be.
 *
 * **When a world computed these numbers**, the range came out of running the
 * map many times over, each run a coherent set of numbers the model would have
 * stood behind, and the sentence says so and then admits in its last clause
 * that nobody has checked the claim against anything that resolved.
 *
 * **When nothing computed them** — which is every number in this build, because
 * the engine's route does not exist yet — the range is what whoever wrote the
 * number down said about how sure they were. Saying "across 2 000 versions of
 * this map" over a number nobody ran through a map would be the plainest kind
 * of lie this product can tell, so it says the other thing instead.
 *
 * The chip picks between them by one fact: whether the world it is drawing
 * reports how many versions were run. Nothing else changes when the engine
 * lands.
 */
function modelNote(p: number, lo: number, hi: number, versions: number | undefined): Note {
  if (versions === undefined) {
    return {
      label: "stated range · not computed",
      sentence:
        "This range is stated, not computed — it says how sure the elicitation was. " +
        "Nothing has worked this number through the map yet.",
    };
  }
  return {
    label:
      `model interval, uncalibrated · how sure we are of ${toTwoFigures(p)} — ` +
      `not how much the world can move`,
    sentence:
      `Across ${inThousands(versions)} versions of this map — each one a set of numbers this ` +
      `model would have stood behind — the answer landed between ${toTwoFigures(lo)} and ` +
      `${toTwoFigures(hi)} eight times in ten. Nobody has checked whether that 8-in-10 holds ` +
      `up; no claim on this map has resolved yet.`,
  };
}

/** What the reader's own chip says about itself. */
function userNote(p: number, lo: number, hi: number): Note {
  return {
    label: `your own number · ${toReading(p, lo, hi)}`,
    sentence:
      "This is the number you gave. It sits beside the model's and the market's and is " +
      "never averaged with either of them.",
  };
}

/** What a market chip says about itself. */
function marketNote(lo: number, hi: number): Note {
  return {
    label: "market, as a venue is quoting it",
    sentence:
      `The likelihood is the middle of the best bid and the best offer; the range, ` +
      `${toRange(lo, hi)}, is the spread between them. It is what somebody will trade this ` +
      `claim at, not an opinion about it.`,
  };
}

/** Work out the three lines a chip shows, and the note behind it. */
function readChip(
  owner: BeliefOwner,
  slot: Known<Ranged>,
  standing: Standing | undefined,
  versions: number | undefined,
): {
  reading: string;
  under: string | null;
  spoken: string;
  note: Note;
  numeric: boolean;
  step: LikelihoodStep | null;
} {
  // A claim the reader has supposed true is true in every simulated world, so
  // the chip shows the word rather than a number. Inventing one — .98, or 1.0 —
  // would invite the reader to wonder about the other two per cent of a thing
  // they themselves declared settled.
  if (standing !== undefined) {
    return {
      reading: standing.words,
      under: null,
      spoken: `${OWNER_WORDS[owner]}: ${standing.words}`,
      note: { label: standing.words, sentence: standing.reason },
      numeric: false,
      step: null,
    };
  }

  if (slot.reading === undefined) {
    const absence = slot.absence;
    return {
      reading: absence.words,
      // The reader's own empty slot says what to do about it; every other
      // absence keeps its sentence for the shelf, where there is room for it.
      under: owner === "user" ? "add yours" : null,
      spoken: `${OWNER_WORDS[owner]}: ${absence.words}. ${absence.reason}`,
      note: { label: absence.words, sentence: absence.reason },
      numeric: false,
      step: null,
    };
  }

  const { p, lo, hi } = slot.reading;
  const note =
    owner === "model"
      ? modelNote(p, lo, hi, versions)
      : owner === "user"
        ? userNote(p, lo, hi)
        : marketNote(lo, hi);
  return {
    reading: toTwoFigures(p),
    under: toRange(lo, hi),
    spoken: `${OWNER_WORDS[owner]}: ${toReading(p, lo, hi)}`,
    note,
    numeric: true,
    step: likelihoodStep(p),
  };
}

/** What a belief chip needs to draw itself. */
export interface BeliefChipProps {
  /** Whose number this is. There are three, and they are never averaged. */
  readonly owner: BeliefOwner;
  /** The number, or the absence that stands where it would have been. */
  readonly slot: Known<Ranged>;
  /** A word shown instead of a likelihood, when the claim stands on the reader's say-so. */
  readonly standing?: Standing;
  /**
   * How many versions of the map were run to produce this number.
   *
   * Absent means nothing computed it, and the model chip then says so rather
   * than describing a run that never happened.
   */
  readonly versions?: number;
}

/** One of the three belief chips on a tile. */
export function BeliefChip({ owner, slot, standing, versions }: BeliefChipProps) {
  const noteId = useId();
  const [pinned, setPinned] = useState(false);
  const { reading, under, spoken, note, numeric, step } = readChip(owner, slot, standing, versions);

  return (
    <span className="belief-chip" data-owner={owner} data-reading={numeric ? "number" : "words"}>
      {/* The face of the chip is the thing you can reach, so that looking at it
          with a pointer and arriving at it with the keyboard do the same thing.
          Pressing it pins the note open, for a reader who wants both hands free
          while they read it; pressing again puts it away. It is named by the
          whole reading — the number and its range together — because that is how
          the chip would be said out loud, and the range is never left off. */}
      <button
        className="belief-chip__face"
        type="button"
        aria-label={spoken}
        aria-describedby={noteId}
        aria-controls={noteId}
        aria-expanded={pinned}
        onClick={() => setPinned((was) => !was)}
      >
        <span className="belief-chip__owner">{OWNER_WORDS[owner]}</span>
        <span className="belief-chip__reading">
          {/* The bounded bar the likelihood rides on: one of five brightnesses,
              the same size whatever the number is. Brightness is the whole of
              what it says and the number printed beside it is the reading, so
              the bar only has to clear three to one while the number clears four
              and a half. It is drawn on the chip, never over a whole tile:
              tile-wide brightness is already spent on the other world in a diff
              and on the hover lens, and three meanings on one channel means none
              of them reads. */}
          {step === null ? null : (
            <span className="belief-chip__bar" data-step={step} aria-hidden="true" />
          )}
          <span className="belief-chip__figure">{reading}</span>
        </span>
        <span className="belief-chip__under">{under ?? ""}</span>
      </button>
      <span className="belief-chip__note" id={noteId} data-pinned={pinned ? "yes" : "no"}>
        <span className="belief-chip__note-label">{note.label}</span>
        <span className="belief-chip__note-sentence">{note.sentence}</span>
      </span>
    </span>
  );
}

/**
 * Where a tile's ports are, and the one place that says so.
 *
 * A **port** is the socket a wire attaches to. Every tile has four: a pair on
 * the left edge for arrows arriving and a pair on the right for arrows leaving,
 * and in each pair the upper socket is for an arrow that fires once and stays
 * fired, the lower for one that only holds while its cause holds. What a wire
 * means is visible at the socket before you follow it anywhere.
 *
 * **A port's place is declared, not discovered — and that is the whole point of
 * this file.** The drawing library draws a wire between two ports, and left to
 * itself it finds out where a port is by measuring the page, through the very
 * same browser notification a busy browser drops. A wire whose ends were never
 * measured is not drawn at all: the map holds every claim, in its place, and
 * says nothing about how they are joined, which is the wrong picture of the
 * argument and a silent one. #37 met the same dropped notification as tiles
 * that never appeared and answered it by telling the library each tile's box
 * outright. A box is not a port, so the wire half of it was left over. This is
 * the rest of the same answer: told its box *and* where its ports sit, a tile
 * can have its wires drawn on the first frame with nothing measured at all.
 *
 * So every number a port has is written here, and written **once**. The tile
 * puts these numbers straight onto the element it draws; the drawing library is
 * handed the same numbers; `wires/plates.ts` places a plate against them. This
 * file must never read a port's place back off the screen, and nothing else may
 * write one down a second time — two places that have to agree are two places
 * that one day will not.
 */

import type { NodeHandle } from "@xyflow/react";
import { Position } from "@xyflow/react";
import type { LinkMode } from "../world";
import { TILE_WIDTH } from "./geometry";

/**
 * How wide a port is, in pixels — two steps of the eight-pixel grid the whole
 * interface sits on.
 *
 * It straddles the tile's edge, half of it inside and half outside, which is
 * why it is exactly twice the standoff below.
 */
export const PORT_WIDTH = 16;

/** How tall a port is, in pixels: enough for one bar, a gap and a second bar. */
export const PORT_HEIGHT = 6;

/**
 * How far past the tile's edge a wire attaches, in pixels.
 *
 * A wire that met the tile flush would have its last few pixels drawn under the
 * tile's own outline. Eight pixels clear is one step of the grid.
 */
export const PORT_STANDOFF = 8;

/**
 * How far down a tile each of the two sockets sits, as a share of its height.
 *
 * A share rather than a number of pixels, because a tile is as tall as its own
 * content: the pair has to stay evenly spaced about the middle on a tile of any
 * height. Read by `wires/plates.ts` as well, which has to know where a wire
 * will start before a single wire has been drawn.
 */
export const DOWN_THE_TILE: Readonly<Record<LinkMode, number>> = {
  trigger: 0.38,
  sustain: 0.62,
};

/** What a port is called. These four names are what a wire names its ends by. */
export type PortId = "in-trigger" | "in-sustain" | "out-trigger" | "out-sustain";

/** One socket on the edge of a tile. */
export interface Port {
  /** Its name, which is what a wire asks for. */
  readonly id: PortId;
  /** Whether wires leave from it or arrive at it. */
  readonly kind: "source" | "target";
  /** Which edge of the tile it is on. */
  readonly edge: Position;
  /** Which kind of push attaches here. Also what the socket is drawn as. */
  readonly mode: LinkMode;
}

/**
 * The four ports every tile has, in the order they are drawn.
 *
 * Arriving before leaving, and within each pair the one that fires once before
 * the one that holds — on each edge, the same top-to-bottom order its two
 * sockets are drawn in, so each side of the list reads the way that side of the
 * tile looks.
 */
export const PORTS: readonly Port[] = [
  { id: "in-trigger", kind: "target", edge: Position.Left, mode: "trigger" },
  { id: "in-sustain", kind: "target", edge: Position.Left, mode: "sustain" },
  { id: "out-trigger", kind: "source", edge: Position.Right, mode: "trigger" },
  { id: "out-sustain", kind: "source", edge: Position.Right, mode: "sustain" },
];

/** A port's box, in the tile's own coordinates, with the tile's corner at zero. */
export interface PortBox {
  /** Its left edge. Negative on the left of a tile: the port straddles the edge. */
  readonly x: number;
  /** Its top edge. */
  readonly y: number;
  /** How wide it is. */
  readonly width: number;
  /** How tall it is. */
  readonly height: number;
}

/**
 * Where this port sits on a tile of this height.
 *
 * The one piece of arithmetic in this file, and every other number here and in
 * the tile comes out of it. The box straddles the tile's edge so that the wire
 * attaches a clear eight pixels outside it, and it is centred on the share of
 * the height the socket sits at.
 *
 * @param height How tall the tile is — the same number the layout reserved for
 *   it and the same number the tile is drawn at. A tile that grew a line
 *   because an edit touched it moves its ports down with it, and this is where
 *   that happens.
 * @param port Which of the four.
 */
export function portBox(height: number, port: Port): PortBox {
  return {
    x: port.edge === Position.Left ? -PORT_STANDOFF : TILE_WIDTH + PORT_STANDOFF - PORT_WIDTH,
    y: height * DOWN_THE_TILE[port.mode] - PORT_HEIGHT / 2,
    width: PORT_WIDTH,
    height: PORT_HEIGHT,
  };
}

/**
 * Every port of a tile this tall, in the shape the drawing library takes them.
 *
 * Handed over with the tile's box, so that the library knows where both ends of
 * every wire are before it has measured anything. It keeps measuring afterwards
 * and rebuilds these from what it measures; the numbers are the same numbers,
 * because the tile was drawn from them.
 *
 * @param height How tall the tile is.
 */
export function portsOf(height: number): NodeHandle[] {
  return PORTS.map((port) => ({
    id: port.id,
    type: port.kind,
    position: port.edge,
    ...portBox(height, port),
  }));
}

/**
 * Which port a wire of this kind leaves from, and which it arrives at.
 *
 * @param mode Whether the push fires once or has to keep holding.
 */
export function portsForAWire(mode: LinkMode): {
  readonly source: PortId;
  readonly target: PortId;
} {
  return mode === "sustain"
    ? { source: "out-sustain", target: "in-sustain" }
    : { source: "out-trigger", target: "in-trigger" };
}

/**
 * How big a tile is, and how far the map may be zoomed.
 *
 * The automatic layout has to know how big every tile is *before* the browser
 * has drawn one — it works out where the tiles go from the shape of the map
 * alone, and it cannot wait for measurements. So a tile's height is computed
 * here, from the claim's own content, by a plain function of plain data. That
 * keeps the layout a pure function of the map: the same map lays out the same
 * way every time, and the layout can be tested without a browser.
 *
 * The block heights below were measured once in the browser against the stored
 * example and are written down rather than read back at run time. If the tile's
 * stylesheet changes a line height or a gap, these change with it — and the
 * check for that is visual: a tile whose numbers are wrong has a gap at the
 * bottom or loses its last line.
 */

import type { ClaimView } from "../world";

/** How wide a tile is. Settled: 280 pixels, and measurable on any screenshot. */
export const TILE_WIDTH = 280;

/**
 * How tall a tile may be, at the least and at the most.
 *
 * "Clamped height" is a floor and a ceiling with the content deciding in
 * between — not one height for every tile. The floor is what a tile holding
 * only a heading, a one-line claim and the three belief chips comes to; the
 * ceiling is what the densest tile in the stored example needs, which is the
 * hypothesis, with a three-line claim, a reason and two evidence clippings.
 * Both are on the eight-pixel grid.
 */
export const TILE_MIN_HEIGHT = 152;
/**
 * The ceiling was 272, which was what the densest tile in the stored example
 * needed **before a tile could carry badges**. A claim the reader supposed and a
 * later edit pushed back down says so on its own face, in one line that names
 * the edit responsible — *Supposed · Oct 1 → Retracted · Oct 2 · by "a confirmed
 * military strike on Iranian territory"* — and that line is three lines wide on
 * a 280-pixel tile. A ceiling that cut it off would hide the one thing the tile
 * is there to say.
 */
export const TILE_MAX_HEIGHT = 320;

/* ---- The blocks a tile is made of, in pixels --------------------------- *
 * Measured in the browser, at the type sizes and line heights `tile.css`
 * sets. Every one of them is a height the browser actually produced. */

/** Top and bottom padding together: twelve pixels each. */
const PADDING = 24;

/** The gap between one block and the next. */
const GAP = 8;

/** The heading row: what kind of claim this is, and when it settles. */
const HEADER = 21;

/**
 * One line of the claim, at fifteen pixels over a line height of 1.35.
 *
 * Rounded up wherever it is used, never down: a line that is given a quarter of
 * a pixel less than it needs loses the bottom of its descenders.
 */
const CLAIM_LINE = 20.25;

/**
 * The three belief chips: owner, number and range, with the rule above them.
 *
 * Measured at 69 in the browser, which is two pixels more than the 67 written
 * here before the chips grew their brightness bars. A row that is two pixels
 * short takes them off the bottom of the tile.
 */
const BELIEF_RAIL = 69;

/**
 * The line a dead end prints saying why nothing here can be traded. Clamped to
 * two lines, and the only reason any tile prints for itself.
 */
const FINDING = 35;

/** One evidence clipping, and the gap between two of them. */
const CLIPPING = 21;
const CLIPPING_GAP = 4;

/**
 * One line of a claim's badges, and the hairline and padding the badges
 * themselves add to the block once.
 *
 * Thirteen pixels over a line height of 1.35 is 17.5, and each badge is drawn
 * with a hairline round it and a pixel of padding, which lifts a line box to
 * about 19. Both measured in the browser against the stored example's strike
 * branch, where the tallest badge line in the product — *Supposed · Oct 1 →
 * Retracted · Oct 2 · by "…"* — runs to three lines.
 */
const BADGE_LINE = 19;
const BADGE_PADDING = 4;

/**
 * Roughly how many characters of a badge fit on one line.
 *
 * The badges flow across the same 256 pixels the claim wraps in, set at thirteen
 * pixels in the interface face, whose average character is about six and a half
 * pixels wide — so about thirty-eight. An estimate, and safe to be one for the
 * same reason the claim's is: the same number decides both how tall the tile is
 * and how much room the badges get, so the two cannot disagree.
 */
const BADGE_CHARACTERS_PER_LINE = 38;

/** The separator drawn between one badge and the next, counted into the width. */
const BADGE_SEPARATOR = " → ";

/**
 * Roughly how many characters of the claim fit on one line.
 *
 * The claim has 256 pixels to wrap in (244 on the two tiles whose outline cuts
 * into one side) and is set at fifteen pixels in the interface face, whose
 * average character is about eight pixels wide — so about thirty-three.
 *
 * It is an estimate, and it is safe to be one because the same number decides
 * both how tall the tile is and how many lines the claim is allowed to show.
 * The two cannot disagree: if the estimate is generous the tile has a little
 * room to spare, and if it is mean the claim stops one line earlier than it
 * might have. Neither case can push a word out of the box.
 */
const CLAIM_CHARACTERS_PER_LINE = 33;

/** The most lines of the claim a tile ever shows. The rest lives in the panel. */
const CLAIM_MAX_LINES = 3;

/**
 * How many lines of the claim this tile shows.
 *
 * @param claim The claim, in the words the map serves it in.
 */
export function claimLines(claim: string): number {
  const wanted = Math.ceil(claim.length / CLAIM_CHARACTERS_PER_LINE);
  return Math.min(CLAIM_MAX_LINES, Math.max(1, wanted));
}

/**
 * How many lines this claim's badges take.
 *
 * Zero when it has none, which is every claim on a map nobody has edited.
 *
 * @param claim The claim the tile is for.
 */
export function badgeLines(claim: ClaimView): number {
  const badges = claim.badges ?? [];
  if (badges.length === 0) {
    return 0;
  }
  const characters =
    badges.reduce((sum, badge) => sum + badge.words.length, 0) +
    BADGE_SEPARATOR.length * (badges.length - 1);
  return Math.max(1, Math.ceil(characters / BADGE_CHARACTERS_PER_LINE));
}

/** Round up to the eight-pixel grid the whole interface sits on. */
function toGrid(height: number): number {
  return Math.ceil(height / 8) * 8;
}

/**
 * How tall this claim's tile wants to be, before the grid, the floor and the
 * ceiling are put to it.
 *
 * Kept apart from the bounding below because a height that has been bounded is
 * no longer a height you can do arithmetic with: two clamped numbers added
 * together can land outside the very bounds each of them was clamped into.
 *
 * @param claim The claim the tile is for.
 * @param badges How many lines the badges take. Passed in rather than read off
 *   the claim so that a caller reserving a line of its own for one badge can
 *   say so without building a second claim to say it with.
 */
function naturalHeight(claim: ClaimView, badges: number): number {
  const blocks: number[] = [HEADER, Math.ceil(CLAIM_LINE * claimLines(claim.claim)), BELIEF_RAIL];

  // The foot of the tile: the reason a slot has no number, and the evidence
  // clippings. It is only there when there is something to put in it — and
  // when the badges arrive, having one of those will put it there too.
  const foot: number[] = [];
  if (claim.kind === "not_tradeable" && claim.beliefs.market.absence !== undefined) {
    foot.push(FINDING);
  }
  const clippings = claim.evidence.length;
  if (clippings > 0) {
    foot.push(CLIPPING * clippings + CLIPPING_GAP * (clippings - 1));
  }
  if (badges > 0) {
    foot.push(BADGE_LINE * badges + BADGE_PADDING);
  }
  if (foot.length > 0) {
    blocks.push(foot.reduce((a, b) => a + b, 0) + GAP * (foot.length - 1));
  }

  return PADDING + blocks.reduce((a, b) => a + b, 0) + GAP * (blocks.length - 1);
}

/** Put a wanted height on the eight-pixel grid, inside the floor and the ceiling. */
function bounded(natural: number): number {
  return Math.min(TILE_MAX_HEIGHT, Math.max(TILE_MIN_HEIGHT, toGrid(natural)));
}

/**
 * How tall this claim's tile is: as tall as its own content, on the grid, and
 * inside the floor and the ceiling.
 *
 * @param claim The claim the tile is for.
 */
export function tileHeight(claim: ClaimView): number {
  return bounded(naturalHeight(claim, badgeLines(claim)));
}

/**
 * How tall a box this claim's tile needs when how far its number moved gets a
 * line of its own.
 *
 * A tile is as tall as its own content, and the layout has to know that before
 * the browser has drawn one — so the height is a plain function of the claim.
 * This adds one thing to it: **the movement line is not packed in with whatever
 * the edits had to say.** On the busiest tile on the map, *Supposed · Oct 1 →
 * Retracted · Oct 2 · by "…"* already runs to three lines, and stringing a
 * reading on the end of that run pushes a line out of the box.
 *
 * The extra line is measured rather than written down — the words and the
 * reading are each measured on their own — so if the badge line height ever
 * changes, this changes with it.
 *
 * **The wanted height is worked out once and bounded once.** This was first
 * written as three already-bounded heights added and subtracted — with the
 * badges, with the reading, less the empty tile — and a bounded height is not a
 * number to do arithmetic with. The floor is added twice and taken off once, so
 * an ordinary tile is handed more room than its content needs (the busiest tile
 * on the stored example: 296 pixels reserved against the 280 it wants), and
 * nothing holds the total under the ceiling that each of the three was clamped
 * into.
 *
 * @param claim The claim the tile is for.
 */
export function roomFor(claim: ClaimView): number {
  const badges = claim.badges ?? [];
  const said = badges.filter((badge) => badge.movement !== true);
  const moved = badges.filter((badge) => badge.movement === true);
  const lines =
    said.length === 0 || moved.length === 0
      ? badgeLines(claim)
      : badgeLines({ ...claim, badges: said }) + badgeLines({ ...claim, badges: moved });
  return bounded(naturalHeight(claim, lines));
}

/* ---- Zoom --------------------------------------------------------------- */

/**
 * The smallest a word may be drawn on the reader's screen, in pixels.
 *
 * This is the rule the two zoom numbers below are worked out from, rather than
 * a number chosen for how it looked.
 */
const SMALLEST_READABLE_TEXT = 11;

/** The smallest and largest of the three type sizes, as `tokens.css` sets them. */
const SMALLEST_TEXT = 13;
const LARGEST_TEXT = 22;

/**
 * Below this zoom a tile stops showing everything and shows a summary instead.
 *
 * **This was 0.6, and it is now eleven over thirteen — about 0.85.** The plan
 * settled on 0.6 before the type scale was settled, and the two turned out not
 * to fit together: a full tile's smallest words are thirteen pixels, so at 0.6
 * zoom they arrive on the glass at under eight, which breaks the rule that
 * nothing is ever drawn below eleven. Eleven over thirteen is the exact zoom at
 * which thirteen-pixel type lands at eleven pixels, so a full tile is only ever
 * shown at or above it, and below it the summary takes over — which sets every
 * word in the largest size and so clears the floor all the way down.
 */
export const SUMMARY_BELOW_ZOOM = SMALLEST_READABLE_TEXT / SMALLEST_TEXT;

/**
 * How far out the map may be zoomed.
 *
 * The summary sets every word it draws in the largest of the three type sizes,
 * so the floor is the one zoom at which that size arrives at eleven pixels:
 * eleven over twenty-two, which is a half.
 */
export const SMALLEST_ZOOM = SMALLEST_READABLE_TEXT / LARGEST_TEXT;

/** How far in the map may be zoomed. Past this a tile is merely large. */
export const LARGEST_ZOOM = 1.4;

/**
 * The smallest type size a tile draws at this zoom, in pixels, before the map's
 * own scaling is applied.
 *
 * Multiply it by the zoom and you have what lands on the reader's screen, which
 * is what `layout.test.ts` checks never falls below eleven.
 *
 * @param zoom How far the map is zoomed in, where 1 is life size.
 */
export function smallestTextAt(zoom: number): number {
  return zoom < SUMMARY_BELOW_ZOOM ? LARGEST_TEXT : SMALLEST_TEXT;
}

/** The smallest a word is ever drawn on the reader's screen, in pixels. */
export const TEXT_FLOOR = SMALLEST_READABLE_TEXT;

/* ---- The first frame ----------------------------------------------------- */

/** A rectangle in the map's own coordinates. */
export interface Box {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

/** How far the map is moved and zoomed to put something in front of the reader. */
export interface Frame {
  /** How far in the map is zoomed, where 1 is life size. */
  readonly zoom: number;
  /** How far the map is slid sideways, in screen pixels. */
  readonly x: number;
  /** How far the map is slid up or down, in screen pixels. */
  readonly y: number;
}

/** The breathing room left around the map when it is framed, as a share of its size. */
const FIRST_FRAME_MARGIN = 0.04;

/** The gap left at the edge when the map is too big to fit and has to be panned. */
const EDGE_GAP = 16;

/**
 * How the map is framed the first time it is drawn — and the one promise that
 * framing makes: **the first frame never shows summary tiles.**
 *
 * The obvious rule is "fit the whole map". On a wide screen with the panel beside
 * it that lands at about 0.8 zoom on the stored example, which is under the zoom
 * at which a full tile's smallest words would be drawn below eleven pixels — so
 * every tile would open as a summary, and the reader's first sight of the
 * product would be seven boxes with a headline and three numbers in them.
 *
 * So the rule has a floor, and the floor is the same eleven-pixel rule
 * everything else here is derived from: frame the whole map if it fits at a
 * readable size, and if it does not, keep the readable size and start at the
 * map's beginning, on the left, where the hypothesis is. The reader pans to the
 * rest. A tile changes representation rather than shrinking; the same principle,
 * applied to the frame rather than to the tile.
 *
 * @param map Everything the frame has to hold, in the map's own coordinates.
 * @param canvas How much room there is for it, in screen pixels.
 */
export function firstFrame(map: Box, canvas: { width: number; height: number }): Frame {
  const fits = Math.min(
    canvas.width / (map.width * (1 + FIRST_FRAME_MARGIN)),
    canvas.height / (map.height * (1 + FIRST_FRAME_MARGIN)),
  );
  // Never blown up past life size, however small the map; never shrunk past the
  // point where a full tile would have to become a summary.
  const zoom = Math.max(SUMMARY_BELOW_ZOOM, Math.min(1, fits));
  const place = (room: number, start: number, size: number): number => {
    const shown = size * zoom;
    return shown <= room ? (room - shown) / 2 - start * zoom : EDGE_GAP - start * zoom;
  };
  return {
    zoom,
    x: place(canvas.width, map.x, map.width),
    y: place(canvas.height, map.y, map.height),
  };
}

/** How many tiles a single layer may show before the rest are collapsed into one. */
export const TILES_PER_LAYER = 7;

