file.content:
/**
 * What an arrow's data turns into on screen — every lookup in one place.
 *
 * A wire has to say five things at once, and every one of them has to survive a
 * screenshot printed in grey:
 *
 *   1. **what kind of push it is** — the stroke's pattern;
 *   2. **how hard it pushes** — the stroke's width, in four steps;
 *   3. **whether it has to keep holding** — a wire that holds is drawn as two
 *      parallel strokes, a wire that fires once as a single stroke;
 *   4. **whether it loops back** — it runs over the top of the map and carries
 *      the delay in days;
 *   5. **where it came from** — a mark of one, two or three dots at its tail.
 *
 * Not one of those is a colour. Every wire is drawn in the same muted ink, and a
 * wire's hue says nothing at all.
 *
 * One more lookup lives here because it is the same kind of thing: which of the
 * five brightness steps a likelihood is painted with, which is the only part of
 * the colour law that needs a function rather than a stylesheet.
 *
 * **Nothing in this file is arithmetic.** Picking a stroke width or a band of
 * words is a *comparison* of one number against fixed thresholds written down
 * below — the same kind of thing as asking whether a date is in the past. No
 * expression here adds, multiplies or averages two numbers read off the map, and
 * none may ever be added: the moment the canvas works out a number of its own
 * there are two engines on the map and they disagree.
 */

import type { LinkMode, LinkShape, Provenance } from "../../world";

/* ---- How likely a claim is: the one lookup the colour law needs ---------- *
 *
 * Brightness is the channel that carries how likely a claim is, and the five
 * steps of it are `--p-0` … `--p-4` in `styles/tokens.css`. This is the lookup
 * that says which step a likelihood is painted with. It lives here, beside the
 * arrow's lookups, because it is the same kind of thing: a comparison against
 * fixed thresholds, never a calculation. */

/** One of the five brightness steps a likelihood is painted with. */
export type LikelihoodStep = 0 | 1 | 2 | 3 | 4;

/**
 * Which of the five brightness steps this likelihood is painted with.
 *
 * | Likelihood | Step |
 * |---|---|
 * | 0 to under .2 | 0 |
 * | .2 to under .4 | 1 |
 * | .4 to under .6 | 2 |
 * | .6 to under .8 | 3 |
 * | .8 to 1 | 4 |
 *
 * Five steps are a glance, never a reading. The exact number and its range are
 * printed beside the bar every time, so nobody is ever asked to tell step two
 * from step three by eye.
 *
 * @param p How likely the claim is to come out true, from 0 to 1.
 */
export function likelihoodStep(p: number): LikelihoodStep {
  if (p < 0.2) {
    return 0;
  }
  if (p < 0.4) {
    return 1;
  }
  if (p < 0.6) {
    return 2;
  }
  if (p < 0.8) {
    return 3;
  }
  return 4;
}

/* ---- How hard it pushes: four widths and five bands of words ------------- *
 *
 * The two granularities differ on purpose and nothing is lost by it, because
 * the signed number is printed beside the words every time: `+1.6 · a strong
 * push toward`. The stroke is a glance; the words and the number are the
 * reading.
 *
 * Four widths, because a fifth is not tellable apart at a hairline. Five bands
 * of words, because prose can carry a distinction a hairline cannot — the four
 * anchors the map's own rules name (half, one, two and three) with the gaps
 * between them filled and one band added below a quarter. */

/** The four stroke widths, in pixels, from thinnest to thickest. */
export const WIRE_WIDTHS = [1, 2, 3, 4] as const;

/** A stroke width, in pixels. */
export type WireWidth = (typeof WIRE_WIDTHS)[number];

/**
 * The size of a push, without its sign.
 *
 * Width comes from how hard an arrow pushes and never from which way: an arrow
 * that makes its target less likely is drawn exactly like one that makes it
 * more likely, and the sign is carried by the printed sign and by a word.
 *
 * @param strength How hard the arrow pushes, signed, at full precision.
 */
function sizeOf(strength: number): number {
  return strength < 0 ? -strength : strength;
}

/**
 * Which of the four stroke widths this push is drawn at.
 *
 * A comparison against three thresholds, and nothing else:
 *
 * | The size of the push | Stroke |
 * |---|---|
 * | under 0.5 | 1 pixel |
 * | 0.5 to under 1.25 | 2 pixels |
 * | 1.25 to under 2.25 | 3 pixels |
 * | 2.25 and over | 4 pixels |
 *
 * @param strength How hard the arrow pushes, signed, at full precision.
 */
export function widthFor(strength: number): WireWidth {
  const size = sizeOf(strength);
  if (size < 0.5) {
    return 1;
  }
  if (size < 1.25) {
    return 2;
  }
  if (size < 2.25) {
    return 3;
  }
  return 4;
}

/** One band of the words a push reads back as, and the two sizes it is drawn at. */
interface Band {
  /** Everything below this size falls in this band. `Infinity` for the top one. */
  readonly under: number;
  /** What a push this size, pushing its target toward coming true, reads as. */
  readonly toward: string;
  /** What a push this size, pushing its target away from coming true, reads as. */
  readonly against: string;
}

/**
 * The five bands, smallest first.
 *
 * The anchors behind them: half a point roughly shifts the odds by a fifth, one
 * point triples them, two points is a strong shove and three is close to
 * settling the question. Between the anchors the interface reads a push back in
 * these five bands.
 */
const BANDS: readonly Band[] = [
  { under: 0.25, toward: "a faint push toward", against: "a faint push against" },
  { under: 0.75, toward: "a nudge toward", against: "a nudge against" },
  { under: 1.5, toward: "a clear push toward", against: "a clear push against" },
  { under: 2.5, toward: "a strong push toward", against: "a strong push against" },
  { under: Number.POSITIVE_INFINITY, toward: "close to decisive", against: "close to ruled out" },
];

/**
 * What this push reads back as in words.
 *
 * Which way it pushes is carried by the last word — *toward* or *against* — so
 * the direction survives a picture with no colour in it at all, and so that a
 * push is never mistaken for a direction of financial effect. Those are
 * different things: the arrow into *Brent settles below $68* pushes that claim
 * **toward** coming true, and the price it describes is **falling**.
 *
 * @param strength How hard the arrow pushes, signed, at full precision.
 */
export function pushInWords(strength: number): string {
  const size = sizeOf(strength);
  const band = BANDS.find((one) => size < one.under) ?? BANDS[BANDS.length - 1];
  if (band === undefined) {
    // Unreachable: the last band's ceiling is infinity, so `find` always hits.
    return "a push";
  }
  return strength < 0 ? band.against : band.toward;
}

/**
 * The push as a signed number, the way the interface prints one: `+1.6`, `−1.2`.
 *
 * A proper minus sign rather than a hyphen, and a plus sign always written out,
 * because a reader scanning a column of pushes should never have to work out
 * whether a missing sign means positive or means somebody forgot.
 *
 * One figure after the point, which is the precision the map's own arrows are
 * elicited at. This is not a likelihood and the two-significant-figures rule
 * does not reach it: a push is a signed amount on the scale where separate
 * pushes add up, not a probability.
 *
 * @param strength How hard the arrow pushes, signed, at full precision.
 */
export function pushAsNumber(strength: number): string {
  const size = sizeOf(strength).toFixed(1);
  return strength < 0 ? `−${size}` : `+${size}`;
}

/**
 * The whole reading a wire's chip shows: the number, then the words.
 *
 * @param strength How hard the arrow pushes, signed, at full precision.
 */
export function pushReading(strength: number): string {
  return `${pushAsNumber(strength)} · ${pushInWords(strength)}`;
}

/* ---- What kind of push it is: the stroke's pattern ----------------------- */

/** How one of the three signal shapes is drawn, and what it says. */
interface ShapeDrawing {
  /**
   * The dashes and gaps the stroke is drawn with, or `null` for an unbroken
   * line. Written in the wire's own units when the pattern should look the
   * same on every wire, and in hundredths of the wire's length when it should
   * run its course exactly once from tail to head — see `growsAlongTheWire`.
   */
  readonly dashes: string | null;
  /**
   * True when the pattern is measured in hundredths of this wire's own length,
   * so that it climbs from fine to coarse the same way however long the wire is.
   */
  readonly growsAlongTheWire: boolean;
  /** What this shape does over time, in one line, for the panel. */
  readonly sentence: string;
}

/**
 * The three shapes.
 *
 * - **A one-time spike** is drawn dot-dash: a mark, a gap, a dash, a gap, over
 *   and over. It reads as something that happened once and is fading.
 * - **A switch that holds** is drawn solid. Nothing is broken about it.
 * - **A push that builds** is drawn as dashes that grow from fine at the cause
 *   to coarse at the effect, so the picture itself climbs. A gradient along the
 *   stroke was the other option and it was not taken: brightness already means
 *   how likely a claim is, and a wire that got brighter along its length would
 *   be a second meaning on that channel — and it would read as a lighting
 *   effect rather than as a signal.
 */
const SHAPES: Record<LinkShape, ShapeDrawing> = {
  impulse: {
    dashes: "1 4 7 4",
    growsAlongTheWire: false,
    sentence: "a one-time spike that fades away",
  },
  step: {
    dashes: null,
    growsAlongTheWire: false,
    sentence: "switched on when the delay has run, and held from then on",
  },
  ramp: {
    // Five dashes that grow, one to five, with a gap between each: twenty-five
    // hundredths of the wire's own length, so the climb runs four times from
    // tail to head on a wire of any length.
    //
    // Four times rather than once, and that is the whole of the thinking here.
    // A single climb along the wire is the truer picture, but on a long wire its
    // last stretch is one dash a fifth of the wire long — and a fifth of a wire
    // is a stretch a reader meets on its own, where it is a plain line and says
    // *a switch that holds*. Repeating the climb means that wherever the eye
    // lands, the pattern is growing, which is the thing that had to be legible.
    dashes: "1 2 2 2 3 2 4 2 5 2",
    growsAlongTheWire: true,
    sentence: "climbs from nothing to full size across the delay, then holds",
  },
};

/**
 * How a wire of this shape is stroked.
 *
 * @param shape What the push does over time.
 */
export function strokeFor(shape: LinkShape): ShapeDrawing {
  return SHAPES[shape];
}

/**
 * What this shape does over time, in one line — with the half-life spelled out
 * when there is one.
 *
 * @param shape What the push does over time.
 * @param halfLife Days for a one-time spike to fall to half its size, or null.
 */
export function shapeInWords(shape: LinkShape, halfLife: number | null): string {
  const base = SHAPES[shape].sentence;
  if (shape === "impulse" && halfLife !== null) {
    return `${base}, half gone after ${inDays(halfLife)}`;
  }
  return base;
}

/* ---- Whether it has to keep holding ------------------------------------- */

/** What each of the two kinds of push means, in a sentence rather than a word. */
const MODES: Record<LinkMode, string> = {
  trigger:
    "a domino — it fires once when the cause becomes true, and the effect stays " +
    "pushed and fades on its own. Standing the first domino back up does not " +
    "stand this one back up",
  sustain:
    "an apple on a desk — the push exists only while the cause holds, and it " +
    "vanishes the moment the cause stops",
};

/**
 * What this kind of push means, in a sentence.
 *
 * @param mode Whether the push survives its cause going away.
 */
export function modeInWords(mode: LinkMode): string {
  return MODES[mode];
}

/* ---- How long it takes --------------------------------------------------- */

/**
 * A number of days, the way the interface says one.
 *
 * Whole days are written without a decimal point, because "2.0 days" reads as a
 * measurement and a lag is a count.
 *
 * @param days A number of days.
 */
export function inDays(days: number): string {
  const figure = Number.isInteger(days) ? `${days}` : days.toFixed(1);
  return days === 1 ? "1 day" : `${figure} days`;
}

/**
 * How long after its cause this push arrives, in words.
 *
 * @param lag Days from the cause becoming true to the push reaching full size.
 */
export function lagInWords(lag: number): string {
  return lag === 0 ? "same day" : `after ${inDays(lag)}`;
}

/* ---- Where it came from: one, two or three dots -------------------------- */

/** How many dots an arrow's mark carries. Three steps, never seven. */
export type OriginStep = 1 | 2 | 3;

/**
 * The three steps, and which of the seven receipts fall in each.
 *
 * Three rather than seven, because the question a picture can answer is *is
 * there a document behind this, or is it the model talking*. The seven-way
 * distinction is not something anybody reads off a picture, so the exact word
 * lives in the panel beside the map, where there is room for it — drawn by the
 * same component, so the mark and the word can never drift apart.
 */
const ORIGIN_STEPS: Record<Provenance, OriginStep> = {
  documented: 3,
  historical: 3,
  market_implied: 3,
  argued: 2,
  user: 2,
  asserted: 1,
  simulated: 1,
};

/** What each of the three steps means, in one line. */
const STEP_MEANINGS: Record<OriginStep, string> = {
  3: "something was fetched, studied or priced",
  2: "a mechanism was stated, or a person typed it",
  1: "the model talking, or a probe",
};

/**
 * How many dots this receipt is drawn with.
 *
 * @param provenance Where the arrow and its number came from.
 */
export function originStep(provenance: Provenance): OriginStep {
  return ORIGIN_STEPS[provenance];
}

/**
 * What a mark of this many dots means, in one line.
 *
 * @param step How many dots the mark carries.
 */
export function originStepMeaning(step: OriginStep): string {
  return STEP_MEANINGS[step];
}

/**
 * What each of the seven receipts says about itself, in the panel.
 *
 * These are facts about our own pipeline, not claims a model makes about its own
 * work. The model never fills one of these in; our code writes it from what
 * actually happened.
 */
const ORIGIN_SENTENCES: Record<Provenance, string> = {
  documented: "sources were fetched and cited, and they are listed above",
  historical: "it comes from a study of what happened in past cases like this one",
  market_implied: "it was read off a price somebody is actually quoting",
  argued: "the model stated a mechanism, and no retrieval step has run for this arrow",
  user: "you put this arrow on the map yourself",
  asserted: "the model asserted it without stating a mechanism — the weakest of the seven",
  simulated: "it came out of a probe run against this claim, not out of the world",
};

/**
 * What this receipt says about itself, in one line.
 *
 * @param provenance Where the arrow and its number came from.
 */
export function originInWords(provenance: Provenance): string {
  return ORIGIN_SENTENCES[provenance];
}

/**
 * The branch panel: your edits, in the order you made them — and the six things
 * you can do to a claim.
 *
 * **A sequence, not a surprise.** Read as a list, the rule that a later edit
 * outranks an earlier supposition is obvious: you supposed the strait reopens,
 * then you added a strike, then you supposed the strike lands, and the strike's
 * arrow was added *after* the supposition, so it is live. Met instead as a number
 * that moved on its own, the same rule reads as a bug. So the sequence is on the
 * screen.
 *
 * **Edits are appended, never rewritten.** There is no way to edit an edit here,
 * and that is deliberate: the branch is the audit trail, and an audit trail you
 * can edit is not one.
 *
 * **The buttons build a branch, and the engine moves the numbers.** Pressing one
 * appends an edit and the panel shows it immediately; the whole branch is then
 * handed to the engine, which works the map's likelihoods through again and says
 * what moved. Nothing on this side works out a number — appending an edit is the
 * whole of what a button does.
 *
 * **One of the six is not on the panel at all.** *Split this claim* is not
 * built, so it is not offered. It was never greyed out — a disabled control says
 * "not for you" and nothing else, and cannot even be asked about with the
 * keyboard — but a row that takes a press and then explains that it can do
 * nothing is still a seventh of this menu spent on an absence. What it would do
 * is written where the rest of the unbuilt work is written, in
 * `spec/multiverse/interventions.md`.
 *
 * **The two that are easiest to confuse say the difference before you press
 * them.** *Suppose this is true* and *This happened* both fix a claim's value,
 * and they differ in what else may move: one cuts the claim loose from its
 * causes and one leaves them connected. That is the distinction this product
 * beats every competitor on, and it used to be spoken only *after* the press.
 * Each now carries the shared vocabulary's own meaning as a subtitle, word for
 * word from the *Interface words* table.
 *
 * **One of the six needs the model, and only that one.** *Add a claim* sends the
 * sentence you type to the part of this product that drafts a whole claim — the
 * wording, the test that settles it, its judge, its date and what it started
 * from — and appends what comes back to the branch like any other edit. The
 * other five are arithmetic in the engine's pure core, which is why a reader
 * with no key still gets the whole multiverse at full fidelity.
 *
 * **Nothing here opens over the map.** No dialog, no scrim, nothing to dismiss:
 * the fields below appear inside this panel, beside the map, which stays live.
 */

import { useEffect, useRef, useState } from "react";
import type { components } from "../api/schema";
import { toDay } from "../graph/diff/days";
import { pushAsNumber, pushInWords } from "../graph/wires/encodings";
import type { BranchView, Edit, Selection, WorldView } from "../world";
import { inFewWords, NOT_ON_THIS_MAP } from "../world/naming";
import { AddAClaim } from "./AddAClaim";
import "./branchPanel.css";

/**
 * The six buttons, word for word from the shared vocabulary's *Interface words*
 * table, and the badge each one earns.
 *
 * Copied, never paraphrased. The six operations keep their code names in the
 * code, in the wire format and in the spec, and **not one of those names ever
 * appears on screen.**
 */
const BUTTONS = {
  supposeTrue: "Suppose this is true",
  supposeFalse: "Suppose this is false",
  happened: "This happened",
  addClaim: "Add a claim",
  changePush: "Change this push",
  splitClaim: "Split this claim",
  ownNumber: "My own number",
} as const;

/**
 * What the two headline operations **mean**, as the shared vocabulary's
 * *Interface words* table states it, for the subtitle under each button.
 *
 * Copied from that table's last column word for word, and kept here beside the
 * buttons they belong to so the two cannot drift. They say the difference
 * *before* the press: *Suppose this is true* cuts the claim loose from its
 * causes, so only what it causes may move; *This happened* leaves its causes
 * connected, so what we believe about them is read again too.
 *
 * **They state the operation's meaning, not this build's arithmetic.** That is
 * the promise the product makes and the one the engine is held to; where the
 * engine falls short of it, the engine is what is repaired.
 */
const MEANS = {
  supposeTrue: "Take this as given, and do not tell me what caused it",
  happened: "This is news — update what came before it too",
} as const;

/** How one edit reads in the list: which button made it, and what it was about. */
function editLine(edit: Edit, world: WorldView): { button: string; about: string; badge: string } {
  const words = (id: string): string => world.claims.find((claim) => claim.id === id)?.claim ?? id;
  switch (edit.op) {
    case "do":
      return {
        button: edit.value ? BUTTONS.supposeTrue : BUTTONS.supposeFalse,
        about: words(edit.target),
        badge: `Supposed · ${toDay(edit.at)}`,
      };
    case "observe":
      return {
        button: BUTTONS.happened,
        about: words(edit.target),
        badge: `Happened · ${toDay(edit.at)}`,
      };
    case "insert":
      return { button: BUTTONS.addClaim, about: edit.words, badge: "Added" };
    case "retune":
      return {
        button: BUTTONS.changePush,
        about:
          `You moved this arrow from ${pushAsNumber(edit.wasStrength)} to ` +
          `${pushAsNumber(edit.strength)} — ${pushInWords(edit.strength)}.`,
        badge: "Retuned",
      };
    case "refine":
      return { button: BUTTONS.splitClaim, about: words(edit.target), badge: "Split" };
    case "believe":
      return {
        button: BUTTONS.ownNumber,
        about: words(edit.target),
        badge: "",
      };
  }
}

/** What the branch panel needs. */
export interface BranchPanelProps {
  /** Every branch on this map, in the order they arrived. */
  readonly branches: readonly BranchView[];
  /** Which branch is open, or `null` for the map as it was written. */
  readonly openId: string | null;
  /** The world on screen, so an edit can be read back in the claim's own words. */
  readonly world: WorldView;
  /** Open a branch, or go back to the map as it was written. */
  readonly onOpen: (id: string | null) => void;
  /** Start a new branch with this name. */
  readonly onFork: (label: string) => void;
  /** Whether the name field is open, because `B` opens it from the map. */
  readonly naming: boolean;
  /** Open or close the name field. */
  readonly onNaming: (open: boolean) => void;
}

/** The branch panel. */
export function BranchPanel({
  branches,
  openId,
  world,
  onOpen,
  onFork,
  naming,
  onNaming,
}: BranchPanelProps) {
  const [name, setName] = useState("");
  const open = branches.find((branch) => branch.id === openId);

  return (
    <section className="branch-panel" aria-label="Your branches">
      <h2 className="branch-panel__heading">Branches</h2>

      <ul className="branch-panel__list">
        <li>
          <button
            className="branch-panel__branch"
            type="button"
            data-open={openId === null ? "yes" : "no"}
            onClick={() => onOpen(null)}
          >
            <span className="branch-panel__chip" data-hue="base" aria-hidden="true" />
            <span className="branch-panel__name">The map as it was written</span>
          </button>
        </li>
        {branches.map((branch) => (
          <li key={branch.id}>
            <button
              className="branch-panel__branch"
              type="button"
              data-open={openId === branch.id ? "yes" : "no"}
              onClick={() => onOpen(branch.id)}
            >
              {/* A branch's hue is on its chip and its lane and nowhere else, and
                  the chip always carries the branch's name — so which branch you
                  are in is readable with no colour at all. */}
              <span className="branch-panel__chip" data-hue={branch.hue} aria-hidden="true" />
              <span className="branch-panel__name">{branch.label}</span>
              <span className="branch-panel__count">
                {branch.edits.length === 1 ? "1 edit" : `${branch.edits.length} edits`}
              </span>
            </button>
          </li>
        ))}
      </ul>

      {naming ? (
        <form
          className="branch-panel__naming"
          onSubmit={(event) => {
            event.preventDefault();
            const label = name.trim();
            if (label !== "") {
              onFork(label);
              setName("");
              onNaming(false);
            }
          }}
        >
          <label className="branch-panel__field-label" htmlFor="branch-name">
            What is this branch called? An unnamed branch is unusable once there are three.
          </label>
          <input
            className="branch-panel__field"
            id="branch-name"
            value={name}
            // biome-ignore lint/a11y/noAutofocus: the reader pressed B to open this field and the next thing they will do is type into it; sending focus anywhere else is a keystroke thrown away.
            autoFocus
            onChange={(event) => setName(event.target.value)}
          />
          <div className="branch-panel__field-actions">
            <button className="branch-panel__go" type="submit">
              Start this branch
            </button>
            <button
              className="branch-panel__cancel"
              type="button"
              onClick={() => {
                setName("");
                onNaming(false);
              }}
            >
              Not now
            </button>
          </div>
        </form>
      ) : (
        <button className="branch-panel__fork" type="button" onClick={() => onNaming(true)}>
          Start a branch
        </button>
      )}

      {open === undefined ? (
        // Where the numbers on the unedited map came from — and there are two
        // answers, told apart by the one thing that says whether anything was
        // worked out: whether the world reports how many versions of the map
        // were run. The engine's answer and the stored example's own numbers are
        // different claims about the world, and a screen that said the same
        // sentence over both would be making the weaker one silently.
        <p className="branch-panel__none">
          {world.versions === undefined
            ? "Nothing has been edited. The map above is exactly as it was written, and every " +
              "number on it is the one the stored example carries — nothing has worked one out."
            : "Nothing has been edited. The map above is exactly as it was written, and every " +
              "number on it was worked out by the engine from that map with nothing done to it."}
        </p>
      ) : (
        <ol className="branch-panel__edits">
          {open.edits.map((edit, index) => {
            const line = editLine(edit, world);
            return (
              // biome-ignore lint/suspicious/noArrayIndexKey: a branch is append-only — no edit is ever rewritten, removed or reordered — so an edit's place in the list is a stable name for it, and it is the name the panel prints beside it.
              <li className="branch-panel__edit" key={`${index}-${line.button}`}>
                <span className="branch-panel__number">{index + 1}</span>
                <span className="branch-panel__about">
                  <span className="branch-panel__button-name">{line.button}</span>
                  <span className="branch-panel__subject">{line.about}</span>
                </span>
                {line.badge === "" ? (
                  <span className="branch-panel__no-badge">
                    no badge — the three-up belief chip is the badge
                  </span>
                ) : (
                  <span className="branch-panel__badge">{line.badge}</span>
                )}
              </li>
            );
          })}
        </ol>
      )}
    </section>
  );
}

/** What the six-button panel needs. */
export interface InterventionPanelProps {
  /** The world on screen. */
  readonly world: WorldView;
  /**
   * The open branch in the engine's own shape, when it can be written down.
   *
   * **Add a claim needs it and nothing else on this panel does.** The route
   * drafts and judges the new claim against the map with the branch folded on —
   * which is the map the reader is looking at — so a claim that contradicts an
   * edit made two minutes ago comes back refused in the validator's own
   * sentence rather than accepted and then breaking the branch it is added to.
   * Absent when the branch cannot be written down in full, which is exactly
   * when there is nothing honest to send.
   */
  readonly branch?: components["schemas"]["Branch"];
  /** What the map is open on: the claim or the arrow the buttons act on. */
  readonly selection: Selection;
  /** Append an edit to the open branch. */
  readonly onEdit: (edit: Edit) => void;
  /** Close the panel. */
  readonly onClose: () => void;
}

/**
 * The six things you can do to a claim, in a panel beside the map.
 *
 * Never a pop-up: it appears in the panel, the map keeps drawing beside it, and
 * closing it loses nothing because nothing is left half-done.
 */
export function InterventionPanel({
  world,
  branch,
  selection,
  onEdit,
  onClose,
}: InterventionPanelProps) {
  const [ownNumber, setOwnNumber] = useState(false);
  const [reading, setReading] = useState({ p: "", lo: "", hi: "" });
  const [pushing, setPushing] = useState(false);
  const [adding, setAdding] = useState(false);
  const [push, setPush] = useState("");
  const [said, setSaid] = useState<string | null>(null);

  /**
   * The panel takes the keyboard when it opens, and that is the reader's own
   * act rather than a theft.
   *
   * `graph/theKeyboard.ts` states the rule the map obeys: **the map takes the
   * keyboard back from nowhere, and never from somewhere.** It is about who
   * decided. A map that pulled a reader out of the palette would be taking a
   * decision they had already taken; this is the opposite — the reader pressed
   * `E`, or took up *Change this claim*, and the one thing they can have meant
   * by it is that they want to be in here.
   *
   * **Without it the keyboard is simply dropped.** The way in from the panel's
   * head unmounts the instant it is pressed, so Tab to it, press Enter, and the
   * keyboard is on nothing at all: the next Tab starts again at the top of the
   * page. The section takes focus rather than the first button, because landing
   * on *Suppose this is true* would put a reader one stray Space away from an
   * edit they did not ask for. Where the keyboard goes when this closes is the
   * screen's to answer, not this panel's, because the thing it came from may no
   * longer exist.
   */
  const panel = useRef<HTMLElement | null>(null);
  useEffect(() => {
    panel.current?.focus();
  }, []);

  const claim =
    selection?.kind === "claim" ? world.claims.find((one) => one.id === selection.id) : undefined;
  const wire =
    selection?.kind === "wire" ? world.links.find((one) => one.id === selection.id) : undefined;

  const say = (line: string) => setSaid(line);

  /**
   * Nothing here is ever disabled. A greyed-out button says "not for you" and
   * nothing else — and it is unreachable by keyboard, which makes it a control a
   * reader cannot even ask about. So a button with nothing to act on says what it
   * needs instead.
   */
  const needsAClaim = (): boolean => {
    if (claim !== undefined) {
      return false;
    }
    say(
      "Choose a claim on the map first — click it, or reach it with the keyboard and the panel " +
        "opens on it.",
    );
    return true;
  };

  /**
   * A claim named for a reader: its own words, in few enough of them to fit.
   * Never its identifier — on a generated map that is a string of machine
   * letters, and even on the stored example "H" tells a reader nothing.
   */
  const nameOf = (id: string): string => {
    const found = world.claims.find((one) => one.id === id);
    return found === undefined ? NOT_ON_THIS_MAP : inFewWords(found.claim);
  };

  return (
    <section
      className="intervene"
      ref={panel}
      // Reachable by script and never a tab stop of its own: the reader tabs
      // through the controls inside it, not through the box round them.
      tabIndex={-1}
      aria-label="Change this claim"
      // What the panel is open on, by its identifier — for a test or a tool to
      // read, the way a tile and a wire already carry theirs. An identifier is
      // never WORDS on the screen; the sentence below names the subject.
      data-about={claim?.id ?? wire?.id ?? ""}
    >
      <header className="intervene__head">
        <h2 className="intervene__heading">Change this</h2>
        <button className="intervene__close" type="button" onClick={onClose}>
          Done
        </button>
      </header>

      <p className="intervene__subject">
        {claim !== undefined
          ? claim.claim
          : wire !== undefined
            ? // An arrow is named the way the Inspector names it: by the words of
              // the claim at each end, never by an identifier. "The arrow you have
              // selected" told a reader nothing about WHICH arrow they were about
              // to change.
              `${nameOf(wire.source)} → ${nameOf(wire.target)}`
            : "Choose a claim or an arrow on the map first — click it, or reach it with the keyboard."}
      </p>

      <div className="intervene__buttons">
        <button
          className="intervene__button"
          type="button"
          onClick={() => {
            if (needsAClaim() || claim === undefined) {
              return;
            }
            onEdit({ op: "do", target: claim.id, value: true, at: world.today });
            say("Take this as given, and do not tell me what caused it.");
          }}
        >
          {BUTTONS.supposeTrue}
          <span className="intervene__hint">{MEANS.supposeTrue}</span>
        </button>
        <button
          className="intervene__button"
          type="button"
          onClick={() => {
            if (needsAClaim() || claim === undefined) {
              return;
            }
            onEdit({ op: "do", target: claim.id, value: false, at: world.today });
            say("Take this as given, and do not tell me what caused it.");
          }}
        >
          {BUTTONS.supposeFalse}
        </button>
        <button
          className="intervene__button"
          type="button"
          onClick={() => {
            if (needsAClaim() || claim === undefined) {
              return;
            }
            onEdit({ op: "observe", target: claim.id, value: true, at: world.today });
            say("This is news — what came before it is read again, not only what comes after.");
          }}
        >
          {BUTTONS.happened}
          <span className="intervene__hint">{MEANS.happened}</span>
        </button>
        {/* **Add a claim** is the one of the six that needs the model, and it
            is now connected: the sentence goes to the one route that drafts a
            claim, the same rules every proposal passes check what comes back,
            and the edit is appended to the branch like any other. It is the same
            control, with the same words and the same refusals, on a stored map
            and on one that has just built itself.

            It is a field rather than a button because a claim starts with a
            sentence somebody types, and the other five act on what is already
            selected. */}
        <button
          className="intervene__button"
          type="button"
          onClick={() => setAdding((was) => !was)}
          aria-expanded={adding}
        >
          {BUTTONS.addClaim}
          <span className="intervene__hint">…but this also happens</span>
        </button>
        <button
          className="intervene__button"
          type="button"
          onClick={() => {
            if (wire === undefined) {
              say(
                "Choose an arrow on the map first. This changes one number on one arrow, and " +
                  "nothing else about it.",
              );
              return;
            }
            setPush(`${wire.strength}`);
            setPushing((was) => !was);
          }}
        >
          {BUTTONS.changePush}
        </button>
        {adding ? (
          <AddAClaim
            baseId={world.baseId}
            {...(branch === undefined ? {} : { branch })}
            andThen="It is on your branch, like every other edit."
            onDrafted={(drafted) => {
              setAdding(false);
              onEdit({
                op: "insert",
                claimId: drafted.proposition.id,
                words: drafted.proposition.claim,
                arrows: drafted.links.map((link) => ({
                  id: link.id,
                  source: link.source,
                  target: link.target,
                })),
                drafted,
              });
            }}
          />
        ) : null}
        {/* **Split this claim is not here at all, and that is the whole of what
            this panel says about it.** It was a row that took a press and then
            explained that it could do nothing. That was honest, and it was
            still a seventh of the one menu this product is demonstrated from
            spent on something a reader cannot take up. A control that is not
            built is not a control: what it would do is written where the other
            unbuilt things are written, in the `refine` row of
            `spec/multiverse/interventions.md`. It comes back as a button on the
            day it does something, with the vocabulary's words already waiting
            for it above. */}
        <button
          className="intervene__button"
          type="button"
          onClick={() => {
            if (needsAClaim()) {
              return;
            }
            setOwnNumber((was) => !was);
          }}
        >
          {BUTTONS.ownNumber}
          <span className="intervene__hint">beside the model's, never averaged with it</span>
        </button>
      </div>

      {pushing && wire !== undefined ? (
        <form
          className="intervene__form"
          onSubmit={(event) => {
            event.preventDefault();
            const moved = Number(push);
            if (!Number.isFinite(moved)) {
              return;
            }
            onEdit({
              op: "retune",
              link: wire.id,
              strength: moved,
              wasStrength: wire.strength,
            });
            setPushing(false);
            say(
              `You moved this arrow from ${pushAsNumber(wire.strength)} to ` +
                `${pushAsNumber(moved)} — ${pushInWords(moved)}. Nothing else about the arrow ` +
                `changed.`,
            );
          }}
        >
          <label className="intervene__label" htmlFor="new-push">
            {`How hard does this arrow push? It is ${pushAsNumber(wire.strength)} — ` +
              `${pushInWords(wire.strength)}. A negative number pushes the other way.`}
          </label>
          <input
            className="intervene__field"
            id="new-push"
            inputMode="decimal"
            value={push}
            onChange={(event) => setPush(event.target.value)}
          />
          {/* Not the button's own words again: two things called *Change this
              push* on one panel is two things a reader has to tell apart. */}
          <button className="intervene__go" type="submit">
            Change it to that
          </button>
        </form>
      ) : null}

      {ownNumber && claim !== undefined ? (
        <form
          className="intervene__form"
          onSubmit={(event) => {
            event.preventDefault();
            const p = Number(reading.p);
            const lo = Number(reading.lo);
            const hi = Number(reading.hi);
            if (!(lo >= 0 && lo <= p && p <= hi && hi <= 1)) {
              say(
                "A likelihood runs from 0 to 1, and the range has to hold the number: the bottom " +
                  "at or below it, the top at or above it.",
              );
              return;
            }
            onEdit({ op: "believe", target: claim.id, belief: { p, lo, hi } });
            setOwnNumber(false);
            setReading({ p: "", lo: "", hi: "" });
            say(
              "Your number now sits beside the model's and the market's on that tile. It is never " +
                "averaged with either of them, and it is not pushed through the map.",
            );
          }}
        >
          <label className="intervene__label" htmlFor="own-p">
            Your likelihood, and the range that says how sure you are of it. Between 0 and 1.
          </label>
          <div className="intervene__three">
            <input
              className="intervene__field"
              id="own-p"
              inputMode="decimal"
              placeholder="likelihood"
              value={reading.p}
              onChange={(event) => setReading((was) => ({ ...was, p: event.target.value }))}
            />
            <input
              className="intervene__field"
              aria-label="the bottom of your range"
              inputMode="decimal"
              placeholder="bottom"
              value={reading.lo}
              onChange={(event) => setReading((was) => ({ ...was, lo: event.target.value }))}
            />
            <input
              className="intervene__field"
              aria-label="the top of your range"
              inputMode="decimal"
              placeholder="top"
              value={reading.hi}
              onChange={(event) => setReading((was) => ({ ...was, hi: event.target.value }))}
