input.content:
/**
 * How many words of fixed prose the panel beside the map prints, section by section.
 *
 * Kent, 2026-09-21: "the side bar is pretty cluttered."
 *
 * This counts the words the panel writes ITSELF — the headings, the labels and
 * the explanatory sentences that are the same on every claim — as opposed to the
 * words that come off the map (a claim's own wording, its resolution criteria, a
 * source's title). Only the first kind can be folded away without losing a fact
 * about the map, so only the first kind is counted.
 *
 * How it counts: every string literal and every run of plain text inside the
 * render bodies of `frontend/src/components/Inspector.tsx`, attributed to the
 * `<Section title="…">` it sits under, with class names, imports, types and
 * comments excluded. It is an approximation of what lands on screen — a sentence
 * behind a condition is counted even when that condition is false today — and it
 * is used only to rank sections against each other.
 *
 * Run: node plans/analysis/scripts/ux-round/C/count-panel-prose.mjs
 */

import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..", "..", "..");

/** Cut the block comments out; they are for the next developer, not the reader. */
function withoutComments(source) {
  return source.replace(/\/\*[\s\S]*?\*\//g, "").replace(/^[ \t]*\/\/.*$/gm, "");
}

/** Every quoted string and every run of JSX text, in order, with its line number. */
function displayStrings(source) {
  const found = [];
  const lines = source.split("\n");
  lines.forEach((line, index) => {
    if (/^\s*(import|export type|import type)\b/.test(line)) {
      return;
    }
    // Quoted strings, minus the ones that are plainly not prose.
    for (const match of line.matchAll(/(["'`])((?:\\.|(?!\1)[^\\])*)\1/g)) {
      const text = match[2];
      if (!/[a-z]{3}/.test(text)) continue;
      if (/^[a-z-]+(__|--)/.test(text)) continue; // a class name
      if (/^[a-z]+([A-Z][a-z]+)+$/.test(text)) continue; // a field name
      if (/^(button|claim|wire|generation|model|user|market|words|movement|beside-the-word|reading|en-GB|summary|full|yes|no|none)$/.test(text)) continue;
      found.push({ line: index + 1, text });
    }
    // Plain text between JSX tags.
    for (const match of line.matchAll(/>([^<>{}]*[a-z]{3}[^<>{}]*)</g)) {
      const text = match[1].trim();
      if (text !== "") found.push({ line: index + 1, text });
    }
  });
  return found;
}

const source = withoutComments(
  readFileSync(join(root, "frontend/src/components/Inspector.tsx"), "utf8"),
);

// Where each section starts, so a string can be attributed to one.
const marks = [];
source.split("\n").forEach((line, index) => {
  const section = line.match(/<Section title="([^"]+)"/);
  if (section) marks.push({ at: index + 1, name: section[1] });
  const fn = line.match(/^function (\w+)/);
  if (fn) marks.push({ at: index + 1, name: `«${fn[1]}»` });
});

const strings = displayStrings(source);
const tally = new Map();
for (const one of strings) {
  let owner = "«top»";
  for (const mark of marks) {
    if (mark.at <= one.line) owner = mark.name;
  }
  const words = one.text.split(/\s+/).filter((w) => /[a-z]/i.test(w)).length;
  const row = tally.get(owner) ?? { words: 0, pieces: 0 };
  row.words += words;
  row.pieces += 1;
  tally.set(owner, row);
}

const rows = [...tally].sort((a, b) => b[1].words - a[1].words);
let total = 0;
for (const [name, row] of rows) {
  total += row.words;
  console.log(`${String(row.words).padStart(5)} words  ${String(row.pieces).padStart(3)} pieces  ${name}`);
}
console.log(`${String(total).padStart(5)} words  TOTAL of the panel's own prose`);

