  return source.replace(/\/\*[\s\S]*?\*\//g, "").replace(/^[ \t]*\/\/.*$/gm, "");
}

/** Every quoted string and every run of JSX text, in order, with its line number. */
function displayStrings(source) {
  const found = [];
  const lines = source.split("\n");
  lines.forEach((line, index) => {
    if (/^\s*(import|export type|import type)\b/.test(line)) {
      return;
    }
    // Quoted strings, minus the ones that are plainly not prose.
    for (const match of line.matchAll(/(["'`])((?:\\.|(?!\1)[^\\])*)\1/g)) {
      const text = match[2];
      if (!/[a-z]{3}/.test(text)) continue;
      if (/^[a-z-]+(__|--)/.test(text)) continue; // a class name
      if (/^[a-z]+([A-Z][a-z]+)+$/.test(text)) continue; // a field name
      if (/^(button|claim|wire|generation|model|user|market|words|movement|beside-the-word|reading|en-GB|summary|full|yes|no|none)$/.test(text)) continue;
      found.push({ line: index + 1, text });
    }
    // Plain text between JSX tags.
    for (const match of line.matchAll(/>([^<>{}]*[a-z]{3}[^<>{}]*)</g)) {
      const text = match[1].trim();
      if (text !== "") found.push({ line: index + 1, text });
    }
  });
